mapper.select:
SELECT cu.id, cu.status, cu.create_time, c.id AS coupon_id, c.title, c.type, c.condition_amount, c.discount_amount, c.discount_rate, c.start_time, c.end_time FROM t_coupon_user cu INNER JOIN t_coupon c ON cu.coupon_id = c.id
cu.user_id = #{userId}
AND cu.status = #{status}
AND c.is_deleted = 0
ORDER BY cu.create_time DESC
